<?php
declare(strict_types=1);
require_once __DIR__ . '/bbs_list_query.php';

require_once __DIR__ . '/../lib/bbs_action.php';

function bbs_action_is_admin(array $user): bool { return strcasecmp((string)($user['role'] ?? $user['Role'] ?? ''),'Admin')===0; }
function bbs_action_actor(array $user): string { return trim((string)($user['id'] ?? $user['EmployeeID'] ?? '')); }
function bbs_action_private_dir(): string { $dir=dirname(__DIR__,2).'/backend/private-uploads/bbs-actions';if(!is_dir($dir))mkdir($dir,0750,true);return$dir; }
function bbs_action_permissions(array $user,array $row): array { $id=bbs_action_actor($user);$admin=bbs_action_is_admin($user);$owner=$id===(string)$row['OwnerEmployeeID'];$verifier=$id===(string)$row['VerifierEmployeeID'];return['isAdmin'=>$admin,'isOwner'=>$owner,'isVerifier'=>$verifier,'canManage'=>$admin||$verifier,'canWork'=>$admin||$owner,'canVerify'=>$admin||$verifier,'canUpload'=>$admin||$owner||$verifier]; }
function bbs_action_allowed(array $user,array $row): bool { if(bbs_action_is_admin($user))return true;$id=bbs_action_actor($user);if(in_array($id,array_map('strval',[$row['OwnerEmployeeID'],$row['VerifierEmployeeID'],$row['ObserverEmployeeID'],$row['ObservedEmployeeID']]),true))return true;return(bool)db_row("SELECT id FROM BBS_Hierarchy_Assignments WHERE SupervisorEmployeeID=? AND MemberEmployeeID=? AND DepartmentID=? AND IsActive=1 AND EffectiveFrom<=CURDATE() AND COALESCE(EffectiveTo,'9999-12-31')>=CURDATE() LIMIT 1",[$id,$row['ObservedEmployeeID'],$row['ObservedDepartmentID']]); }
function bbs_action_detail(int $id,?array $user=null): ?array { $row=db_row("SELECT ca.*,o.ObservationNo,o.ObservationDate,o.ObserverEmployeeID,o.ObserverNameSnapshot,o.ObservedEmployeeID,o.ObservedNameSnapshot,o.ObservedDepartmentID,o.ObservedDepartmentSnapshot,o.ObservedUnitSnapshot,a.ItemCodeSnapshot,a.ItemPromptSnapshot,a.Remark SourceRemark,a.ImmediateAction SourceImmediateAction,owner.EmployeeName OwnerName,owner.CompanyEmail OwnerEmail,verifier.EmployeeName VerifierName FROM BBS_Corrective_Actions ca JOIN BBS_Observations o ON o.id=ca.ObservationID JOIN BBS_Observation_Answers a ON a.id=ca.AnswerID LEFT JOIN employees owner ON owner.EmployeeID=ca.OwnerEmployeeID LEFT JOIN employees verifier ON verifier.EmployeeID=ca.VerifierEmployeeID WHERE ca.id=? LIMIT 1",[$id]);if(!$row)return null;if($user&&!bbs_action_allowed($user,$row))return['denied'=>true];$row['files']=db_rows('SELECT id,ActionID,EvidenceType,OriginalName,MimeType,FileSize,UploadedBy,CreatedAt FROM BBS_Action_Files WHERE ActionID=? ORDER BY CreatedAt,id',[$id]);$row['history']=db_rows('SELECT * FROM BBS_Action_History WHERE ActionID=? ORDER BY CreatedAt,id',[$id]);if($user)$row['permissions']=bbs_action_permissions($user,$row);return$row; }
function bbs_action_access(array $user): array { if(bbs_action_is_admin($user))return['sql'=>'1=1','params'=>[]];$id=bbs_action_actor($user);return['sql'=>"(ca.OwnerEmployeeID=? OR ca.VerifierEmployeeID=? OR o.ObserverEmployeeID=? OR o.ObservedEmployeeID=? OR EXISTS(SELECT 1 FROM BBS_Hierarchy_Assignments h WHERE h.SupervisorEmployeeID=? AND h.MemberEmployeeID=o.ObservedEmployeeID AND h.DepartmentID=o.ObservedDepartmentID AND h.IsActive=1 AND h.EffectiveFrom<=CURDATE() AND COALESCE(h.EffectiveTo,'9999-12-31')>=CURDATE()))",'params'=>[$id,$id,$id,$id,$id]]; }
function bbs_action_select(): string { return "SELECT ca.id,ca.ActionNo,ca.OwnerEmployeeID,ca.VerifierEmployeeID,ca.Priority,ca.DueDate,ca.Description,ca.Status,ca.RowVersion,ca.ClosedAt,ca.ReopenCount,ca.CreatedAt,o.ObservationNo,o.ObservationDate,o.ObserverEmployeeID,o.ObserverNameSnapshot,o.ObservedEmployeeID,o.ObservedNameSnapshot,o.ObservedDepartmentID,o.ObservedDepartmentSnapshot,o.ObservedUnitSnapshot,a.ItemCodeSnapshot,a.ItemPromptSnapshot,owner.EmployeeName OwnerName,verifier.EmployeeName VerifierName,DATEDIFF(ca.DueDate,CURDATE()) DaysRemaining,(SELECT COUNT(*) FROM BBS_Action_Files f WHERE f.ActionID=ca.id AND f.EvidenceType='After') AfterEvidenceCount FROM BBS_Corrective_Actions ca JOIN BBS_Observations o ON o.id=ca.ObservationID JOIN BBS_Observation_Answers a ON a.id=ca.AnswerID LEFT JOIN employees owner ON owner.EmployeeID=ca.OwnerEmployeeID LEFT JOIN employees verifier ON verifier.EmployeeID=ca.VerifierEmployeeID"; }

